<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import { onMounted, ref } from 'vue';
import { cmsApi } from '../api';
import type { Scope, FormData } from '../types';
import { useOperation } from './useOperation';
import MenuItemsEditor from './MenuItemsEditor.vue';
const { t } = useCmsI18n();
const props=defineProps<{scope:Scope;can:(permission:string)=>boolean}>();const {busy,error,run}=useOperation();const rows=ref<FormData[]>([]),targets=ref<FormData[]>([]),dialog=ref(false),form=ref<FormData>({});
async function load(){ if (!(props.can('cms:menu:list'))) return;await run(async()=>{rows.value=await cmsApi.menus(props.scope);});}
function open(row?:FormData){ if (!(props.can(row ? 'cms:menu:edit' : 'cms:menu:create'))) return;form.value=row?JSON.parse(JSON.stringify(row)):{code:'header',name:t('cms.labels.headerNavigation'),status:1,items:[]};dialog.value=true;}
async function save(){ if (!(props.can(form.value.id ? 'cms:menu:edit' : 'cms:menu:create'))) return;await run(async()=>{await cmsApi.saveMenu({...form.value,...props.scope});dialog.value=false;await load();});}
async function remove(row:FormData){
  if(!props.can('cms:menu:delete')||busy.value)return;
  const scope={...props.scope};
  await run(async()=>{await cmsApi.removeMenu({...scope,id:row.id});await load();});
}
function deletionPrompt(row:FormData):string {
  const effect=row.code==='header'?t('cms.labels.deletingThisGroupRestoresTheBuiltInTemplateS'):row.code==='footer'?t('cms.labels.deletingThisGroupKeepsTheBuiltInTemplateS'):t('cms.labels.deletingThisGroupRemovesItsNavigationItemsFromTemplate');
  return t('cms.labels.deleteNavigationGroupValueAndAllItsItemsCategories', { value1: row.name, value2: effect });
}
async function toggle(row:FormData,value:unknown){if(!props.can('cms:menu:status'))return;await run(async()=>{await cmsApi.menuStatus({...props.scope,id:row.id,status:value?1:0});await load();});}
onMounted(async()=>{await load();if(!props.can('cms:menu:list'))return;await run(async()=>{targets.value=await cmsApi.menuTargets(props.scope);});});
</script>
<template><div><el-alert class="navigation-guide" :title="t('cms.labels.navigationGroupsDefineWhereMenusAppearItemsDefineWhich')" :description="t('cms.labels.builtInTemplatesUseTheHeaderGroupAtThe')" type="info" :closable="false" show-icon /><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="toolbar"><el-button v-if="can('cms:menu:create')" type="primary" @click="open()">{{ t('cms.labels.newNavigationGroup') }}</el-button></div><el-table :data="rows"><el-table-column prop="name" :label="t('cms.labels.navigationGroupName')" /><el-table-column prop="code" :label="t('cms.labels.navigationGroupCode')" /><el-table-column :label="t('cms.labels.builtInTemplatePosition')"><template #default="{row}">{{ row.code==='header' ? t('cms.labels.headerNavigation') : row.code==='footer' ? t('cms.labels.footerNavigation') : t('cms.labels.determinedByTemplateUsage') }}</template></el-table-column><el-table-column :label="t('cms.labels.topLevelItems')"><template #default="{row}">{{ row.items.length }}</template></el-table-column><el-table-column :label="t('cms.labels.enabled')"><template #default="{row}"><el-switch :model-value="!!Number(row.status)" :disabled="busy||!can('cms:menu:status')" @change="toggle(row,$event)" /></template></el-table-column><el-table-column :label="t('cms.labels.actions')" min-width="180"><template #default="{row}"><el-button v-if="can('cms:menu:edit')" link @click="open(row)">{{ t('cms.labels.edit') }}</el-button><el-popconfirm v-if="can('cms:menu:delete')" :title="deletionPrompt(row)" width="320" :confirm-button-text="t('cms.labels.confirmDeletion')" :cancel-button-text="t('cms.labels.cancel')" @confirm="remove(row)"><template #reference><el-button link type="danger" :disabled="busy">{{ t('cms.labels.deleteNavigationGroup') }}</el-button></template></el-popconfirm></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="form.id ? t('cms.labels.editNavigationGroup') : t('cms.labels.newNavigationGroup')" width="min(1000px, 96vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.navigationGroupName')"><el-input v-model="form.name" /></el-form-item><el-form-item :label="t('cms.labels.navigationGroupCode')"><p class="field-help">{{ t('cms.labels.headerIsUsedAtTheTopAndFooterAt') }}</p><el-input v-model="form.code" :disabled="!!form.id" placeholder="header / footer" /></el-form-item><el-form-item :label="t('cms.labels.enableNavigationGroup')"><el-switch v-model="form.status" :active-value="1" :inactive-value="0" :disabled="!can('cms:menu:status')" /></el-form-item><p class="field-help">{{ t('cms.labels.navigationItemsArePublicMenuLinksChildItemsAppear') }}</p><MenuItemsEditor :can-status="can('cms:menu:status')" :items="form.items" :targets="targets" /><el-button @click="form.items.push({title:'',target_type:'external',external_url:''})">{{ t('cms.labels.addNavigationItem') }}</el-button></el-form><template #footer><el-button @click="dialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="can(form.id ? 'cms:menu:edit' : 'cms:menu:create')" type="primary" :loading="busy" @click="save">{{ t('cms.labels.saveNavigationGroup') }}</el-button></template></el-dialog></div></template>
<style scoped>.toolbar{margin:16px 0}.navigation-guide{margin-bottom:16px}.field-help{width:100%;margin:0 0 8px;color:var(--el-text-color-secondary);font-size:13px;line-height:1.6}.menu-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:14px 0}.menu-row .el-input,.menu-row .el-select{width:220px}</style>
